<?php /** An adjustment's lines. Data: adjustment, lines, mayEdit, seesCost */ $j = $adjustment; ?>
<div class="card mb-3" id="adjustment-lines"><div class="card-header"><h5 class="card-title mb-0">Lines <span class="text-muted fs-12">(<?= count($lines) ?>)</span></h5></div>
<?php if ($lines === []): ?><div class="card-body text-muted" id="adjustment-lines-empty">No lines yet.</div><?php else: ?>
<div class="table-responsive"><table class="table align-middle mb-0" id="adjustment-lines-table"><thead><tr><th>#</th><th>Ingredient</th><th class="text-end">Change</th><th class="text-end">Cost</th><th>Note</th><th></th></tr></thead><tbody>
<?php foreach ($lines as $l): $neg = (float) $l['qty_delta'] < 0; ?><tr id="adjustment-line-row-<?= $l['line_id'] ?>"><td><?= (int) $l['line_no'] ?></td><td><?= hx_link('/ingredients/' . $l['ingredient_id'], e($l['ingredient'])) ?></td>
    <td class="text-end <?= $neg ? 'text-danger' : 'text-success' ?>"><span class="fw-semibold"><?= e(($neg ? '' : '+') . fmt_num($l['qty_delta'], 4) . ' ' . $l['unit_code']) ?></span> <span class="fs-12 text-muted">(<?= e(fmt_num($l['qty_delta_base'], 3) . ' ' . $l['base_unit_code']) ?>)</span></td>
    <td class="text-end"><?= $seesCost ? ($l['unit_cost_per_base'] === null ? '<span class="text-muted">running</span>' : '$' . e(fmt_num($l['unit_cost_per_base'], 6)) . ' / ' . e($l['base_unit_code'])) : money(null) ?></td><td class="fs-12"><?= e((string) $l['note']) ?></td>
    <td class="text-end"><?php if ($j['status'] === 'draft' && $mayEdit): ?><form method="post" action="/adjustments/line-remove.php" hx-post="/adjustments/line-remove.php" hx-target="#flash" class="d-inline"><?= csrf_field() ?><input type="hidden" name="line" value="<?= $l['line_id'] ?>"><button type="submit" class="btn btn-light btn-sm btn-touch text-danger" id="adjustment-line-remove-<?= $l['line_id'] ?>" aria-label="Remove"><i class="feather-x"></i></button></form><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></div>
